interface Api { fetch(id: number): Promise<Data>; }
class RealApi implements Api { async fetch(id:number){ /* network call */ } }
class ApiProxy implements Api {
  private cache = new Map<number, Data>();
  async fetch(id:number){
    if (this.cache.has(id)) return this.cache.get(id)!;
    const data = await new RealApi().fetch(id);
    this.cache.set(id, data);
    return data;
  }
}

